local topics={
  {id="daily_rest",category="daily_rest",phrases={"歇一会","歇会儿","休息一下","想休息","喘口气","缓一缓"},replies={"找块安全的地方坐会儿。腿是你的，别拿它当无限耐久。","先停一小会儿。事情不会因为你歇口气就全部坏掉。","好，今天不用每一步都赶着走。"}},
  {id="daily_sleep",category="daily_sleep",phrases={"困死了","犯困","想睡觉","好困","睡不着","失眠","熬夜"},replies={"困成这样，就别跟自己较劲了。","现在想睡，还是脑子停不下来？这两种累不一样。","睡前那点没做完的事，可以留给明天。"}},
  {id="daily_joy",category="daily_joy",phrases={"好开心","太开心","好高兴","开心死","真快乐","今天不错"},replies={"看出来了。脚步都比刚才轻。","这次可以得意一下，我批准了。","那就把这一刻记牢，别只记那些倒霉事。"}},
  {id="daily_sad",category="daily_sad",phrases={"难受","想哭","委屈","心情不好","不开心","伤心","很丧"},replies={"想哭就哭。你不用先证明自己受了多大的委屈。","今天已经够难受了，别再拿话戳自己。","是刚才那件事，还是攒了很久？"}},
  {id="daily_stress",category="daily_stress",phrases={"压力","焦虑","烦躁","心乱","绷不住","撑不住"},replies={"先把事情缩成一件。一次背整座山，谁都走不动。","你现在需要一个办法，还是先骂两句？","已经绷到这个程度了，先松开一点。"}},
  {id="daily_proud",category="daily_proud",phrases={"我做到了","成功了","搞定了","过了","赢了","终于打过"},replies={"嗯，是你自己做到的。这次不准说只是运气。","刚才还在担心的人，现在可以直起腰了。","这件事，值得你给自己留点好脸色。"}},
  {id="daily_failure",category="daily_failure",phrases={"失败了","又输了","打不过","做不好","搞砸了"},replies={"先分清楚是方法错了，还是只是这次没成。","输了这一场，又不是把以后都输掉了。","想复盘就挑最关键的一步，别顺带把自己骂一遍。"}},
  {id="daily_selfworth",category="daily_selfworth",phrases={"我没用","废物","我很差","我不行","我真没用","自卑"},replies={"别把一次没做好，改写成你整个人都不行。","你累的时候给自己打分，判得总是特别狠。","你可以说哪里做得不好，别把自己整个抹掉。"}},
  {id="daily_thanks",category="daily_thanks",phrases={"谢谢","感谢","多亏你","幸好有你","辛苦了"},replies={"嗯，收到了。下次也记得护着自己。","少客气一点，多活久一点。","知道了。嘴上谢完，可别又往怪堆里钻。"}},
  {id="daily_apology",category="daily_apology",phrases={"对不起","抱歉","我错了","不是故意的"},replies={"错在哪就改哪，不用一直低着头。","我没打算拿这件事一直罚你。","下次说清楚就行，不需要把自己骂得很难听。"}},
  {id="daily_praise",category="daily_praise",phrases={"真厉害","好厉害","你真棒","太强了","牛逼","牛啊","帅死"},replies={"夸完了？那我就当你是真心的了。","这种话，我倒也不是完全不爱听。","先收下。等下一场再看我表现。"}},
  {id="daily_attachment",category="daily_attachment",phrases={"喜欢你","爱你","抱抱","抱一下","亲亲","贴贴"},replies={"靠近一点可以。别把自己摔进来。","你说得这么直接，我倒有点没地方躲。","嗯。这次不躲你。"}},
  {id="daily_missing",category="daily_missing",phrases={"想你了","好想你","想念你","你想我吗"},replies={"我没走远。只是平时没那么爱吵你。","你终于舍得叫我了。","这句话，下次可以早点说。"}},
  {id="daily_trust",category="daily_trust",phrases={"相信你","信任你","靠你了","交给你了"},replies={"信任不是叫你闭着眼睛往前冲。该停的时候也要停。","能做到的我会去做，做不到的也会直说。","好。那你也别把自己的判断丢掉。"}},
  {id="daily_bored",category="daily_bored",phrases={"无聊","没意思","不知道干嘛","没事做","好闷"},replies={"换件小事做吧。不是所有时间都得拿来拼命。","要聊天，还是给自己找一个很小的目标？","你这是没事可做，还是做什么都提不起劲？"}},
  {id="daily_plans",category="daily_plans",phrases={"接下来干嘛","做什么好","下一步","有什么目标","怎么安排"},replies={"先把活命需要的东西补齐，再挑一件你想做的。","目标先定小一点。大计划最会把人堵在原地。","看看缺什么，再看看想要什么。顺序别全颠倒了。"}},
  {id="daily_choice",category="daily_choice",phrases={"怎么选","选哪个","拿不定主意","纠结","犹豫"},replies={"先说你最不愿意失去什么，答案通常藏在那里。","两边都想要很正常，先挑代价能承受的那边。","选完可以调整，不用把每个决定都当最后一回。"}},
  {id="daily_regret",category="daily_regret",phrases={"后悔","早知道","不该那样","如果当时"},replies={"你现在知道的事，当时的你未必知道。","可以记住代价，不必天天重付一遍。","真想补救，就找还能动的那一步。"}},
  {id="daily_future",category="daily_future",phrases={"以后会怎样","未来","将来","明天怎么办"},replies={"明天还没来。先给它留一顿饭和一个能睡的地方。","不知道全貌，也能先走一小步。","我不替未来保证，但眼前这一步可以好好选。"}},
  {id="daily_past",category="daily_past",phrases={"以前的事","从前","过去","回忆","小时候"},replies={"你最想留下的是那个人，还是那时的自己？","能记得就记得吧，别让回忆只剩下难受的那半截。","过去有好有坏，不用为了往前走把它全扔了。"}},
  {id="daily_friends",category="daily_friends",phrases={"朋友","好友","队友","伙伴","联机队友"},replies={"一起过日子的人，分工比互相猜心思有用。","有话尽早说，别攒到只剩脾气。","有人帮忙很好，也别忘了问问对方缺什么。"}},
  {id="daily_quarrel",category="daily_quarrel",phrases={"吵架","闹别扭","被骂","讨厌我","生我的气"},replies={"先别急着赢那句话。你想把关系说清，还是只想出口气？","气头上的话最省力，收回来却最费劲。","你可以生气，也可以先离开一会儿。"}},
  {id="daily_romance",category="daily_romance",phrases={"谈恋爱","恋人","对象","暗恋","失恋","分手"},replies={"喜欢一个人，别把自己的日子整个交出去。","舍不得和适不适合，有时不是同一回事。","想说就说具体一点，我不拿一句话判你该爱谁。"}},
  {id="daily_work",category="daily_work",phrases={"上班","工作","加班","打工","老板","下班"},replies={"忙完就下班。脑子也得跟着回来，别只让身体回家。","活可以认真做，别把每份委屈都叫成应该。","今天最耗你的，是事情多，还是人太烦？"}},
  {id="daily_study",category="daily_study",phrases={"学习","作业","考试","复习","背书","论文"},replies={"先做最小的一段。翻开比想象自己一口气做完有用。","卡住了就说卡在哪，别只盯着最后的分数。","学不会和现在不会，不是一个意思。"}},
  {id="daily_weekend",category="daily_weekend",phrases={"周末","放假","假期","休假"},replies={"难得有空，别连休息都给自己排成绩。","想出门，还是想安安静静待着？","放假的第一件事，可以是不急着决定做什么。"}},
  {id="daily_music",category="daily_music",phrases={"听歌","音乐","这首歌","这歌","好听","单曲循环","歌声","唱歌","歌单","BGM","bgm"},replies={"有些话说不出口，歌倒是替人说得很明白。","这首是陪你高兴的，还是陪你难过的？","你喜欢的是旋律，还是正好戳中的那句？"}},
  {id="daily_art",category="daily_art",phrases={"画画","绘画","写字","写作","创作","灵感"},replies={"先留一笔。空白比不完美更容易把人困住。","喜欢就慢慢磨，不必每次都拿给别人判。","没灵感的时候，看看具体的东西，别一直逼自己。"}},
  {id="daily_games",category="daily_games",phrases={"游戏","开黑","通关","玩什么","好玩"},replies={"玩到只剩生气，就先停一会儿。你又不欠它工时。","想挑战一点，还是想轻松一点？","喜欢的玩法就继续，不用把每种乐趣都过成任务。"}},
  {id="daily_home",category="daily_home",phrases={"想家","家人","回家","家里","爸妈"},replies={"有地方想回，是很重也很软的一件事。","想联系就发一句吧，不一定非要凑够一大段话。","家里让你挂念的，是人，还是那种不用解释的感觉？"}},
  {id="daily_pet",category="daily_pet",phrases={"小猫","小狗","宠物","猫咪","狗狗"},replies={"它们要的有时很简单，吃饱、安心，还有你回来。","可爱归可爱，该照顾的时候可不能装没看见。","说吧，今天又被哪只小东西拿捏了？"}},
  {id="daily_food",category="daily_food",phrases={"想吃","吃什么","好吃","晚饭","早饭","午饭","宵夜"},replies={"先挑一顿你真的愿意吃的，别饿着肚子一直选。","想吃热的，还是想吃点清爽的？","吃饭这件事，不用每回都等到饿得发抖。"}},
  {id="daily_water",category="daily_water",phrases={"口渴","喝水","水杯","忘记喝水"},replies={"手边有水就喝两口。别等嗓子替你发脾气。","忙归忙，喝口水的工夫总得留给自己。","杯子摆得再近，不端起来也没用。"}},
  {id="daily_body",category="daily_body",phrases={"脖子酸","腰疼","肩膀酸","坐累","眼睛酸"},replies={"先离开屏幕活动一下，别把身体当成不会磨损的工具。","姿势换一换。剩下那点事不会趁你伸懒腰跑掉。","难受就停，不用等到撑不住才算值得休息。"}},
  {id="daily_fishing",category="daily_fishing",phrases={"钓鱼","海钓","鱼竿","钓竿","鱼线","上钩"},replies={"池塘用普通钓竿，海里用海钓竿。别拿错了。","想让我操作，可以说“帮我钓鱼”或“帮我海钓”，再同意接管。","鱼线绷得太紧就得松，急着收反而容易断。"}},
  {id="daily_queen",category="daily_queen",phrases={"蜂后","小蜜蜂","守卫蜂","蜜蜂冲刺","蜂蜜地面"},replies={"蜂蜜地面会拖慢脚步。切回去打本体，也得绕开那层黏糊糊的东西。","初期守卫可以清到最后一只；后面反复补兵，就得靠拉开队形找本体空档。","排箫要留在拉远守卫后用，别让它们刚睡着你又一脚踩回去。"}},
  {id="daily_charge",category="daily_charge",phrases={"梦魇疯猪","发条战车","冲撞","横冲直撞","恐怖之眼"},replies={"直着跑只会把追逐拖长。看准冲撞的朝向，从侧面让过去。","它冲过去以后才是回头的机会，别跟着一起撞。","左右都危险时，退路未必在左右。"}},
  {id="daily_travel",category="daily_travel",phrases={"赶路","走太远","探索","探路","迷路"},replies={"先留一个能认出的参照，再往前走。","走得快很好，知道怎么回来更重要。","你想去找东西，还是只想看看没见过的地方？"}},
  {id="daily_seasons",category="daily_seasons",phrases={"换季","冬天","夏天","秋天","春天"},replies={"季节变起来不等人。准备最好在你还不需要的时候做。","别等第一场雪才想起保暖，也别等冒烟才想起降温。","你最怕的那一季，提前补一点就没那么吓人。"}},
  {id="daily_rain",category="daily_rain",phrases={"下雨","淋湿","雨停","雨天","打雷"},replies={"该收的先收，别站着把自己淋成落汤鸡。","雨声可以慢慢听，湿度条可不会陪你讲情调。","这雨，要是刚好能把烦人的事一起冲走就好了。"}},
  {id="daily_dark",category="daily_dark",phrases={"天黑","太黑","没有光","黑夜","黑暗"},replies={"先把光留住。别为了省那一点东西把命搭上。","夜里可以安静，不能连照明都安静了。","看不清就别急着往前探。"}},
  {id="daily_resources",category="daily_resources",phrases={"没材料","缺材料","资源不够","没木头","没石头"},replies={"缺哪样就先补哪样，别一边缺一边扩摊子。","材料不会因为计划漂亮就自己长进背包。","先看库存，再动手。来回跑最会偷时间。"}},
  {id="daily_inventory",category="daily_inventory",phrases={"包满","背包满","装不下","东西太多","整理背包"},replies={"先分出现在要用的、能存的、真没必要带的。","背包不是仓库的替身，你也不是搬运车。","别等满到走不动，才想起刚才那件已经能放下。"}},
  {id="daily_base",category="daily_base",phrases={"基地","建家","安家","造家","家建哪"},replies={"先看出入方便、关键资源和安全，景色可以慢慢补。","住下来以后最常走的路，比第一眼好不好看更实在。","别把所有东西挤成一团，火可不管你摆得多努力。"}},
  {id="daily_boss",category="daily_boss",phrases={"打boss","打Boss","打BOSS","挑战boss","挑战Boss"},replies={"先确认装备和退路。勇敢不是连失败时怎么走都不想。","打谁就看谁的招，不能把所有大家伙都当木桩。","想让我接手就直说，控制权还是得由你点头。"}},
  {id="daily_curiosity",category="daily_curiosity",phrases={"为什么","怎么回事","什么意思","啥意思","没搞懂"},replies={"你指的是刚才哪一步？给我一个具体的东西，我比较好判断。","把最让你不明白的那一点挑出来，别把整团疑问一起扔着。","我可能没抓到你指的对象，补一个名字就行。"}},
  {id="daily_uncertain",category="daily_uncertain",phrases={"不知道","不确定","说不清","想不明白","不知道怎么说"},replies={"不确定也可以先说个大概，不用先整理成标准答案。","先排除最不想要的，有时比立刻找答案容易。","说不清就从刚才发生的那件小事说起。"}},
  {id="daily_quietcompany",category="daily_quietcompany",phrases={"别说话","安静会儿","陪我待会","陪着我","什么都不想做"},replies={"好。先不催你做任何事。","这里给你留着，不挤你。","那就待一会儿。"}},
  {id="daily_meaning",category="daily_meaning",phrases={"意义","活着","人生","值得吗","为了什么"},replies={"有些日子先把自己照顾好，就已经是一件很具体的事。","不一定所有东西都得立刻找出一个宏大的理由。","你在问这件事值不值得，还是在问自己值不值得？"}},
  {id="daily_complimentself",category="daily_complimentself",phrases={"我厉害吧","我棒不棒","快夸我","夸夸我"},replies={"这次确实干得漂亮。你刚才做对的那一步，我可没漏看。","厉害。要不要我顺便刻在树上，省得你待会儿又问？","该夸的时候我不会省这几个字。"}},
  {id="daily_comfortrequest",category="daily_comfortrequest",phrases={"安慰我","哄哄我","说点好听的","哄我一下"},replies={"今天辛苦了。这句话不用拿满分才配听。","有些难受不是你的错，先别把责任全往身上揽。","你已经撑了好一阵了，可以放松一点了。"}},
  {id="daily_separation",category="daily_separation",phrases={"你会走吗","你会离开吗","别离开我","别丢下我"},replies={"我跟着你。想停下也可以直接告诉我。","你担心的是现在找不到我，还是担心每次都得自己扛？","至少这一段路，你不用一个人走。"}},
  {id="daily_identityagain",category="daily_identityagain",phrases={"你是我吗","你是另一个我","你是谁","第二人格"},replies={"你可以把我当成与你同行的另一个影子。游戏里的我，不替你定义现实中的你。","我用你的样子，也留一点自己的脾气。","像你，不代表每句话都得和你一样。"}},
  {id="daily_forget",category="daily_forget",phrases={"忘了","记不住","忘记了","忘带","记性不好"},replies={"先别急着骂记性。重要的东西给自己留个记号。","忘的是东西，还是本来想做的那件事？","能补就补，补不了就换一步走。"}},
  {id="daily_anger",category="daily_anger",phrases={"气死了","生气","气得","烦死了","想骂人"},replies={"要骂就骂具体的事，别顺手把自己也骂进去。","先把手里的危险东西放稳，再发脾气。","这口气先别逼着自己咽，想清楚要冲谁说。"}},
  {id="daily_waiting",category="daily_waiting",phrases={"等等我","等我一下","先等等","慢一点","走慢点"},replies={"行，不催。","你处理完眼前的，我再动。","知道了，脚步收回来。"}},
  {id="daily_notice",category="daily_notice",phrases={"看这个","你看","快看","看见了吗","注意到了吗"},replies={"你想让我看的是哪个？说个名字，免得我看偏。","又发现什么了？","说具体点，我可不想一本正经地认错东西。"}},
  {id="daily_hope",category="daily_hope",phrases={"会好起来吗","还有希望","能行吗","怎么办才好"},replies={"先找还能改变的那一小块，不用现在就把全部扛起来。","我不拿空话担保结果。但还能动手，就还有可以试的办法。","你现在需要的是一个能做的步骤，我们就从那里开始。"}},
  {id="daily_smalltalk",category="daily_smalltalk",phrases={"随便聊聊","聊点什么","聊聊天","唠嗑","说点什么"},replies={"今天哪件小事让你多想了一会儿？","要不说说你刚才最得意，或者最想翻白眼的一刻。","这回你挑话题，我少说两句阴阳怪气的。"}}}
local M={rules={},pools={}}
for _,t in ipairs(topics) do M.rules[#M.rules+1]={id=t.id,category=t.category,phrases=t.phrases,priority=65,daily=true};M.pools[t.category]=t.replies end
return M
